html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set customer = frappe.get_doc("Customer", doc.customer) if doc.customer else None -%}

{% set chunk_size = 10 %}
{% set total_items = doc.locations|length %}
{% set chunks = (total_items // chunk_size) + (1 if total_items % chunk_size else 0) %}

<style>
 @page { margin: 5mm; }
body, .print-format {
  margin: 0;
  padding: 0;
  font-family: Arial, sans-serif;
  font-size: 9pt;
}
.wrapper {
  width: 100%;
  padding: 4px;
  border: 1px solid #000;
  box-sizing: border-box;
}
.header { 
  display:flex; flex-direction:column; 
  border-bottom:1px solid #000; 
  padding:6px; position:relative;
}
.company-block { width:65%; }
.company-name { font-weight:bold; font-size:11pt; }
.company-details { font-size:10pt; line-height:1.2; }
.page-info { position:absolute; top:8px; right:8px; font-size:9pt; font-weight:bold; color:#444; }

.info { border-bottom:1px solid #000; display:flex; font-size:10pt; }
.info-left, .info-right { width:50%; padding:6px; }
.info-left { border-right:1px solid #000; }
.info-label { font-weight:bold; width:110px; display:inline-block; }

table.items {
  width:100%; border-collapse:collapse; font-size:10pt;
  table-layout:fixed;
}
.items th {
  border:1px solid #000; padding:4px; background:#f5f5f5;
  text-align:center; font-weight:bold; font-size:10pt;
}
.items th:nth-child(1), .items td:nth-child(1) { width: 5%; }
.items th:nth-child(2), .items td:nth-child(2) { width: 25%; }
.items th:nth-child(3), .items td:nth-child(3) { width: 25%; }
.items th:nth-child(4), .items td:nth-child(4) { width: 10%; }
.items th:nth-child(5), .items td:nth-child(5) { width: 10%; }
.items th:nth-child(6), .items td:nth-child(6) { width: 10%; }
.items th:nth-child(7), .items td:nth-child(7) { width: 15%; }

.items td {
  padding:4px; border:1px solid #000; border-bottom:1px dotted #000;
  word-wrap:break-word;
}
.items tr:last-child td { border-bottom:1px solid #000; }
.text-center { text-align:center; }
.text-right { text-align:right; }
.empty-row td { height:18px; border:none; }

.summary { display:flex; border-top:1px solid #000; font-size:10pt; padding:6px; }
.summary-left { width:60%; }
.summary-right { width:40%; text-align:right; }

.footer { display:flex; font-size:10pt; padding:6px; border-top:1px solid #000; }
.footer-left { width:70%; padding-right:10px; border-right:1px solid #000; line-height:1.4; }
.footer-right { width:30%; text-align:center; }
.sign-space { height:50px; }
.page-break { page-break-before:always; }
</style>

{% for page in range(chunks) %}
<div class="wrapper">

  <!-- Header -->
  <div class="header">
    <div class="page-info">Page {{ page + 1 }} of {{ chunks }}</div>

    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;">
      <div class="logo" style="width:127px; height:115px;">
        <img src="/files/Dacs inc Logo.jpeg" alt="Company Logo" style="max-width:100%; max-height:100%; object-fit:contain;">
      </div>
      <div class="company-block" style="flex-grow:1; padding-left:10px;">
        <div class="company-name">{{ company.name }}</div>
        <div class="company-details">
          Jaya Sai Towers No.40, 1st & 2nd floor, Sajjan Rao Road, Parvathipuram,<br>
          V.V.Puram, BANGALORE - 560004, Karnataka, India<br>
          GSTIN/UIN: 29AAIFD5710C1ZQ<br>
          Phone: 080-41234140 | Email: accounts@dacsinc.in<br>
          Web: www.dacsinc.in
        </div>
      </div>
    </div>

    <div style="text-align:center; border-top:1px solid #000; padding-top:6px; font-size:12pt;">
      <div style="font-weight:bold; font-size:14pt;">PICK LIST</div>
      <div>No: {{ doc.name }} | Date: {{ doc.get_formatted('creation') }}</div>
      <div>Status: {{ doc.status }}</div>
    </div>
  </div>

  <!-- Customer Info -->
  <div class="info">
    <div class="info-left">
      {% if customer %}
        <div><strong>M/s. {{ doc.customer_name }}</strong></div>
        <div>{{ customer.customer_type or "Customer" }}</div>
        <div><span class="info-label">GST No</span>: {{ customer.gstin or "N/A" }}</div>
      {% else %}
        <div><strong>Internal Pick</strong></div>
      {% endif %}
      <div><span class="info-label">Warehouse</span>: {{ doc.parent_warehouse or "-" }}</div>
    </div>
    <div class="info-right">
      <div><span class="info-label">Purpose</span>: {{ doc.purpose }}</div>
      <div><span class="info-label">Delivery Status</span>: {{ doc.delivery_status or "-" }}</div>
    </div>
  </div>

  <!-- Item Table -->
  <table class="items">
    <thead>
      <tr>
        <th>Sl No</th>
        <th>Item Code</th>
        <th>Description</th>
        <th>Warehouse</th>
        <th>Qty</th>
        <th>Picked Qty</th>
        <th>Sales Order</th>
      </tr>
    </thead>
    <tbody>
      {% set start = page * chunk_size %}
      {% set end = (page + 1) * chunk_size %}
      {% set items_on_page = doc.locations[start:end] %}

      {% for item in items_on_page %}
      <tr>
        <td class="text-center">{{ loop.index + start }}</td>
        <td>{{ item.item_code }} - {{ item.item_name }}</td>
        <td>{{ item.description or "" }}</td>
        <td class="text-center">{{ item.warehouse or "-" }}</td>
        <td class="text-center">{{ item.qty or 0 }}</td>
        <td class="text-center">{{ item.picked_qty or 0 }}</td>
        <td class="text-center">{{ item.sales_order or "-" }}</td>
      </tr>
      {% endfor %}

      {% if (items_on_page|length) < chunk_size %}
        {% for i in range((items_on_page|length), chunk_size) %}
        <tr class="empty-row">
          <td colspan="7">&nbsp;</td>
        </tr>
        {% endfor %}
      {% endif %}
    </tbody>
  </table>

  {% if page + 1 == chunks %}
  <!-- Summary -->
  <div class="summary">
    <div class="summary-left">
      <strong>Total Items:</strong> {{ doc.locations|length }}<br>
      <strong>Total Qty:</strong> {{ doc.locations | sum(attribute='qty') }}<br>
      <strong>Total Picked:</strong> {{ doc.locations | sum(attribute='picked_qty') }}
    </div>
    <div class="summary-right">
      <strong>Status:</strong> {{ doc.status }}<br>
      <strong>Delivery Status:</strong> {{ doc.delivery_status or "N/A" }}
    </div>
  </div>

  <!-- Footer -->
  <div class="footer">
    <div class="footer-left">
      <strong>Notes:</strong><br>
      Ensure all picked items are verified before dispatch.<br>
      Handle items carefully to prevent damage.
    </div>
    <div class="footer-right">
      For <strong>{{ doc.company }}</strong><br><br><br><br>
      <div style="border-bottom:1px solid #000; width:80%; margin:0 auto;"></div>
      Authorised Signatory
    </div>
  </div>
  {% endif %}

</div>

{% if not loop.last %}
<div class="page-break"></div>
{% endif %}
{% endfor %}
